//! TypeScript source text: the generated-file header, the module layout,
//! literals, names and imports.
//!
//! The text follows the lint rules of the package: a blank line between
//! two statements of a module, numeric separators in long integers, and
//! double-quoted strings.

/// The first line of every generated module. `write` removes a stale
/// module of the catalog folder only when it starts with this line.
pub const GENERATED_HEADER: &str =
    "// Generated by horsies-typescript-codegen from horsies-core. Do not edit.";

/// The largest integer that a JavaScript `number` holds exactly
/// (`Number.MAX_SAFE_INTEGER`, 2^53 - 1).
pub const MAX_SAFE_INTEGER: i128 = 9_007_199_254_740_991;

/// The fewest digits of an integer literal that the lint rule groups with
/// numeric separators (`unicorn/numeric-separators-style`).
const SEPARATOR_MINIMUM_DIGITS: usize = 5;

/// The digits of one group between two numeric separators.
const SEPARATOR_GROUP_DIGITS: usize = 3;

/// The text of a module: the header, then `sections` with one blank line
/// between two of them, and one newline at the end. A section is one
/// statement of the module, or the block of its imports; the trailing
/// newlines of a section are dropped. Pure.
pub fn module_text(sections: &[String]) -> String {
    let mut text = String::from(GENERATED_HEADER);
    text.push('\n');
    for section in sections {
        text.push('\n');
        text.push_str(section.trim_end_matches('\n'));
        text.push('\n');
    }
    text
}

/// A string literal in double quotes, with the escapes of
/// `JSON.stringify`: `"`, `\` and U+0000 to U+001F. Pure.
pub fn string_literal(text: &str) -> String {
    let mut literal = String::with_capacity(text.len() + 2);
    literal.push('"');
    for character in text.chars() {
        match character {
            '"' => literal.push_str("\\\""),
            '\\' => literal.push_str("\\\\"),
            '\u{8}' => literal.push_str("\\b"),
            '\u{c}' => literal.push_str("\\f"),
            '\n' => literal.push_str("\\n"),
            '\r' => literal.push_str("\\r"),
            '\t' => literal.push_str("\\t"),
            control if u32::from(control) < 0x20 => {
                literal.push_str(&format!("\\u{:04x}", u32::from(control)));
            }
            other => literal.push(other),
        }
    }
    literal.push('"');
    literal
}

/// Whether `text` is an ASCII identifier: a letter, `_` or `$`, then
/// letters, digits, `_` or `$`. Pure.
pub fn is_identifier(text: &str) -> bool {
    let mut characters = text.chars();
    match characters.next() {
        Some(first) if first.is_ascii_alphabetic() || first == '_' || first == '$' => characters
            .all(|character| {
                character.is_ascii_alphanumeric() || character == '_' || character == '$'
            }),
        Some(_) | None => false,
    }
}

/// The key of an object member: `name` when it is an identifier, else its
/// string literal. Pure.
pub fn property_key(name: &str) -> String {
    match is_identifier(name) {
        true => name.to_owned(),
        false => string_literal(name),
    }
}

/// `snake_case` to `camelCase`: `task_name` gives `taskName`. Each part
/// after an underscore starts with an upper-case letter; the first part
/// stays as it is. Pure.
pub fn camel_case_of_snake(snake: &str) -> String {
    let mut text = String::with_capacity(snake.len());
    for (position, part) in snake.split('_').enumerate() {
        match position {
            0 => text.push_str(part),
            _ => text.push_str(&upper_first(part)),
        }
    }
    text
}

/// `snake_case` to `PascalCase`: `not_recorded` gives `NotRecorded`. Pure.
pub fn pascal_case_of_snake(snake: &str) -> String {
    snake.split('_').map(upper_first).collect()
}

/// `PascalCase` to `camelCase`: `ReportedByChild` gives `reportedByChild`.
/// Only the first letter changes. Pure.
pub fn camel_case_of_pascal(pascal: &str) -> String {
    let mut characters = pascal.chars();
    match characters.next() {
        Some(first) => first.to_lowercase().chain(characters).collect(),
        None => String::new(),
    }
}

/// `part` with its first letter in upper case. Pure.
fn upper_first(part: &str) -> String {
    let mut characters = part.chars();
    match characters.next() {
        Some(first) => first.to_uppercase().chain(characters).collect(),
        None => String::new(),
    }
}

/// Whether a JavaScript `number` holds `value` exactly. Pure.
pub fn is_safe_integer(value: i128) -> bool {
    (-MAX_SAFE_INTEGER..=MAX_SAFE_INTEGER).contains(&value)
}

/// The literal of an integer, with a numeric separator between groups of
/// three digits when it has five digits or more: `4242`, `10_000`,
/// `-2_147_483_648`. Pure.
pub fn integer_literal(value: i128) -> String {
    let digits = value.unsigned_abs().to_string();
    let sign = match value < 0 {
        true => "-",
        false => "",
    };
    match digits.len() < SEPARATOR_MINIMUM_DIGITS {
        true => format!("{sign}{digits}"),
        false => format!("{sign}{}", grouped_digits(&digits)),
    }
}

/// The literal of a `bigint`: [`integer_literal`] with the `n` suffix. Pure.
pub fn bigint_literal(value: i128) -> String {
    format!("{}n", integer_literal(value))
}

/// `digits` with `_` between groups of three, counted from the right. Pure.
fn grouped_digits(digits: &str) -> String {
    let first_group = match digits.len() % SEPARATOR_GROUP_DIGITS {
        0 => SEPARATOR_GROUP_DIGITS,
        rest => rest,
    };
    let mut text = String::with_capacity(digits.len() + digits.len() / SEPARATOR_GROUP_DIGITS);
    for (position, digit) in digits.chars().enumerate() {
        let starts_group = position >= first_group
            && (position - first_group).is_multiple_of(SEPARATOR_GROUP_DIGITS);
        if starts_group {
            text.push('_');
        }
        text.push(digit);
    }
    text
}

/// The specifier of the generated module `stem`, as a string literal:
/// `"./status.ts"`. Pure.
pub fn module_specifier(stem: &str) -> String {
    string_literal(&format!("./{stem}.ts"))
}

/// The import of the values `names` from the generated module `stem`.
/// Pure.
pub fn import_values(names: &[&str], stem: &str) -> String {
    format!(
        "import {{ {} }} from {};",
        names.join(", "),
        module_specifier(stem)
    )
}

/// The type-only import of `names` from the generated module `stem`. Pure.
pub fn import_types(names: &[&str], stem: &str) -> String {
    format!(
        "import type {{ {} }} from {};",
        names.join(", "),
        module_specifier(stem)
    )
}

/// An exported type alias of the union of `members`: on one line for one
/// member, else one member per line, each after `| `. Pure.
///
/// An empty `members` is a defect of the caller: a union of nothing is
/// `never`, which no model type means.
pub fn union_alias(name: &str, members: &[String]) -> String {
    match members {
        [] => panic!("the union {name} has no member"),
        [single] => format!("export type {name} = {single};"),
        several => {
            let mut text = format!("export type {name} =");
            for member in several {
                text.push_str("\n  | ");
                text.push_str(member);
            }
            text.push(';');
            text
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_module_has_the_header_and_a_blank_line_between_sections() {
        assert_eq!(
            module_text(&[
                "import type { A } from \"./a.ts\";\n".to_owned(),
                "export const B = 1;".to_owned(),
            ]),
            format!(
                "{GENERATED_HEADER}\n\nimport type {{ A }} from \"./a.ts\";\n\nexport const B = 1;\n"
            )
        );
    }

    #[test]
    fn a_module_without_sections_is_the_header() {
        assert_eq!(module_text(&[]), format!("{GENERATED_HEADER}\n"));
    }

    #[test]
    fn a_literal_escapes_as_json_stringify() {
        assert_eq!(string_literal("PENDING"), "\"PENDING\"");
        assert_eq!(
            string_literal("a\"b\\c\nd\te\r\u{8}\u{c}"),
            "\"a\\\"b\\\\c\\nd\\te\\r\\b\\f\""
        );
        assert_eq!(string_literal("\u{1}\u{1f}"), "\"\\u0001\\u001f\"");
        assert_eq!(string_literal("é/\u{2028}"), "\"é/\u{2028}\"");
    }

    #[test]
    fn an_identifier_is_a_bare_key_and_other_text_is_quoted() {
        assert_eq!(property_key("taskName"), "taskName");
        assert_eq!(property_key("$x_1"), "$x_1");
        assert_eq!(property_key("HRS-001"), "\"HRS-001\"");
        assert_eq!(property_key("1st"), "\"1st\"");
        assert_eq!(property_key(""), "\"\"");
    }

    #[test]
    fn snake_case_becomes_camel_case_and_pascal_case() {
        assert_eq!(camel_case_of_snake("task_name"), "taskName");
        assert_eq!(camel_case_of_snake("sqlstate"), "sqlstate");
        assert_eq!(camel_case_of_snake("max_wait_ms"), "maxWaitMs");
        assert_eq!(pascal_case_of_snake("not_recorded"), "NotRecorded");
        assert_eq!(pascal_case_of_snake("served"), "Served");
    }

    #[test]
    fn pascal_case_becomes_camel_case() {
        assert_eq!(camel_case_of_pascal("ReportedByChild"), "reportedByChild");
        assert_eq!(camel_case_of_pascal("UserOverBound"), "userOverBound");
        assert_eq!(camel_case_of_pascal(""), "");
    }

    #[test]
    fn a_safe_integer_fits_a_number() {
        assert!(is_safe_integer(MAX_SAFE_INTEGER));
        assert!(is_safe_integer(-MAX_SAFE_INTEGER));
        assert!(!is_safe_integer(MAX_SAFE_INTEGER + 1));
        assert!(!is_safe_integer(-MAX_SAFE_INTEGER - 1));
    }

    #[test]
    fn integers_of_five_digits_or_more_have_separators() {
        assert_eq!(integer_literal(0), "0");
        assert_eq!(integer_literal(4242), "4242");
        assert_eq!(integer_literal(-1000), "-1000");
        assert_eq!(integer_literal(10_000), "10_000");
        assert_eq!(integer_literal(100_000), "100_000");
        assert_eq!(integer_literal(1_000_000), "1_000_000");
        assert_eq!(integer_literal(-2_147_483_648), "-2_147_483_648");
        assert_eq!(
            bigint_literal(i128::from(u64::MAX)),
            "18_446_744_073_709_551_615n"
        );
        assert_eq!(bigint_literal(7), "7n");
    }

    #[test]
    fn imports_name_the_module_with_its_extension() {
        assert_eq!(
            import_values(&["TaskStatus"], "status"),
            "import { TaskStatus } from \"./status.ts\";"
        );
        assert_eq!(
            import_types(&["CoreCause", "NoCause"], "error_detail"),
            "import type { CoreCause, NoCause } from \"./error_detail.ts\";"
        );
    }

    #[test]
    fn a_union_of_one_member_is_one_line() {
        assert_eq!(
            union_alias("Only", &["\"A\"".to_owned()]),
            "export type Only = \"A\";"
        );
    }

    #[test]
    fn a_union_of_several_members_has_one_line_per_member() {
        assert_eq!(
            union_alias("Two", &["\"A\"".to_owned(), "\"B\"".to_owned()]),
            "export type Two =\n  | \"A\"\n  | \"B\";"
        );
    }

    #[test]
    #[should_panic(expected = "the union Empty has no member")]
    fn a_union_of_nothing_is_a_defect() {
        let _never = union_alias("Empty", &[]);
    }
}
